
public class Operators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		//Operadores nos permiten relaizar operaciones sobre valores 
		
		//Operadores aritmeticos
		var a = 15;
		var b = 10;
		
		System.out.println(a + b);
		System.out.println(a - b);
		System.out.println(a * b);
		System.out.println(a / b);
		
		
	
	
	
	}

}

